local questInfo={}
for _,p in ipairs(WP.eraObjectiveSamples or {}) do questInfo[p.zone..":"..p.quest]=p end
for zone,packed in pairs(groups) do
 for token in packed:gmatch("[^,]+") do
  local n=#token
  local quest=tonumber(token:sub(1,n-4),36)
  local x=tonumber(token:sub(n-3,n-3),16)
  local y=tonumber(token:sub(n-2,n-2),16)
  local count=tonumber(token:sub(n-1,n),16)
  local info=questInfo[zone..":"..quest]
  if quest and x and y and count and info then
   WP.eraQuestCells[#WP.eraQuestCells+1]={zone=zone,quest=quest,x=(x+.5)/16,y=(y+.5)/16,cx=x,cy=y,count=count,required=info.required,level=info.level,name=info.name,source="QuestieDB Vanilla 1.0.6 quest-cell extraction"}
